SELECT tenant_key,company_id,sample_order_id,color_id,seq,color_code,color_name,color_hex FROM dev_sample_order_color
WHERE tenant_key=#{tenant} AND company_id=#{companyId}

    AND sample_order_id IN #{id}
AND false
ORDER BY sample_order_id,seq,color_id LIMIT 10001

SELECT tenant_key,company_id,sample_order_id,size_group_id,seq,size_code FROM dev_sample_order_size
WHERE tenant_key=#{tenant} AND company_id=#{companyId}

    AND sample_order_id IN #{id}
AND false
ORDER BY sample_order_id,seq,size_code LIMIT 10001

