UPDATE dev_sample_order_color c SET company_id=#{newCompany}
        FROM dev_sample_order o WHERE o.tenant_key=#{tenant} AND o.company_id=#{newCompany} AND o.sample_id=#{sampleId}
        AND c.tenant_key=#{tenant} AND c.company_id=#{oldCompany} AND c.sample_order_id=o.id

UPDATE dev_sample_order_size c SET company_id=#{newCompany}
        FROM dev_sample_order o WHERE o.tenant_key=#{tenant} AND o.company_id=#{newCompany} AND o.sample_id=#{sampleId}
        AND c.tenant_key=#{tenant} AND c.company_id=#{oldCompany} AND c.sample_order_id=o.id
